import React from 'react';
import ReactDOM from 'react-dom';
import { Overlay, DatePicker, NumberPicker } from '@alifd/next';
import '@alifd/next/dist/next.css';

const { Popup } = Overlay;

// Overlay Position Bug Demo
function OverlayDemo() {
  return (
    <div
      style={{
        height: '300px',
        overflow: 'auto',
        border: '1px solid #ccc',
        position: 'relative',
        marginBottom: '40px'
      }}
    >
      <div style={{ height: '600px', padding: '20px' }}>
        <Popup
          trigger={<DatePicker placeholder="Select date" />}
          triggerType="click"
          // Render the overlay into the same scroll container
          container={trigger => trigger.parentNode}
          followTrigger={false}
        >
          <div style={{ padding: '10px' }}>
            <DatePicker placeholder="Inner picker" />
          </div>
        </Popup>

        {/* Add vertical whitespace so container scroll appears */}
        <div style={{ height: '500px' }} />
      </div>
    </div>
  );
}

// NumberPicker innerBefore/innerAfter Bug Demo
function NumberPickerDemo() {
  return (
    <div
      style={{
        padding: '20px',
        border: '1px solid #999',
        display: 'inline-block',
        marginTop: '20px'
      }}
    >
      <NumberPicker
        defaultValue={0}
        // supply a custom prefix — this styling will be misaligned
        innerBefore={<span style={{ color: '#333', margin: '0 6px' }}>before</span>}
        // attempt a suffix (currently unsupported) — layout will break or not render
        innerAfter={<span style={{ color: '#333', margin: '0 6px' }}>after</span>}
      />
    </div>
  );
}

ReactDOM.render(
  <div style={{ padding: '40px' }}>
    <h2>1. Overlay Position Bug</h2>
    <OverlayDemo />
    <h2>2. NumberPicker innerBefore/innerAfter Bug</h2>
    <NumberPickerDemo />
  </div>,
  document.getElementById('root')
);
